{
  "programName": "2026 Lanford Family Transportation Construction Worker Memorial Scholarship Program",
  "eligibility": {
    "requirements": [
      "Applicants must be the sons, daughters, or legally adopted children of transportation construction industry workers killed or permanently disabled in the line of duty.",
      "The applicant’s parent must have been employed by a transportation construction firm or a transportation public agency at the time of their death or disabling injury.",
      "The applicant's educational institution must require a high school diploma or GED for admission."
    ],
    "preferences": [],
    "exceptions": []
  },
  "amountCount": "Scholarships have a value of up to $10,000. More than $750,000 in financial aid has been awarded since inception.",
  "cycle": {
    "open": "Applications must be submitted online by April 3, 2026.",
    "deadline": "April 3, 2026"
  },
  "applicationControl": {
    "label": "Submit your application online",
    "href": "https://artbafoundation.org",
    "offlineMethod": "Applications must be submitted online."
  },
  "essayInstructions": "A typewritten statement, no longer than 200 words, prepared by the applicant that explains their reasons for wanting to continue their education.",
  "renewal": "Scholarship awards are not transferable and are forfeited if the recipient withdraws or fails to meet academic standards. Recipients diagnosed with a medical condition may have the award held for up to 12 months.",
  "conflicts": "Scholarship award money will be held for up to 24 months if the recipient is called to active duty under Title 10.",
  "sourceQuotations": [
    "Applications that do not provide all of the following information will not be considered.",
    "By applying for the ARTBA-TDF 'Lanford Family Transportation Construction Worker Memorial Scholarship' and providing copies of a personal statement and photograph, the applicant thereby grants permission for ARTBA-TDF to use the statement and photographs for scholarship-related publicity and promotional purposes."
  ]
}

